from pathlib import Path
import hashlib,json,re,subprocess,time,statistics
ROOT=Path(__file__).resolve().parent.parent
WORK=ROOT/'build/d100-cost';WORK.mkdir(exist_ok=True)
OLD=ROOT/'build/d099-cost';COMPILER=ROOT/'build/release/mmay'
source={'unhoisted':ROOT/'build/d100-notes-before','hoisted':Path('/workspace/Projects/Marimay/marimay-notes')}
binaries={'d099':OLD/'after-release'}
for phase,folder in source.items():
 binary=WORK/phase
 subprocess.run([str(COMPILER),'build',str(folder),'--release','--allow-read',str(OLD),'--allow-write',str(OLD),'--output',str(binary)],capture_output=True,check=True)
 binaries[phase]=binary
notes=[{'id':i,'text':'Синтетическая заметка 🌿 для проверки порядка и сохранности','tags':['проверка','язык']} for i in range(1,6099)]
def encode(items):return json.dumps({'version':1,'nextId':6099,'notes':items},ensure_ascii=False,separators=(',',':')).encode()
data=encode(notes);assert len(data)==1047786
assert hashlib.sha256(data).hexdigest()=='2c48707982e285d3253064a0c886224e5685b16aa07fcf4e8e353b84f6d2a3ad'
file=OLD/'working.json';records=[]
for case,args,expected,after in [('show-last',['show','6098'],f"#6098 {notes[-1]['text']} [проверка, язык]\n".encode(),data),('remove-last',['remove','6098'],'Удалена заметка №6098.\n'.encode(),encode(notes[:-1]))]:
 for repetition in range(7):
  phases=list(binaries);phases=phases[repetition%3:]+phases[:repetition%3]
  if repetition%2:phases.reverse()
  for phase in phases:
   file.write_bytes(data);start=time.monotonic()
   run=subprocess.run(['/usr/bin/time','-l',str(binaries[phase]),'--db',str(file),*args],capture_output=True,timeout=120)
   elapsed=time.monotonic()-start
   assert run.returncode==0 and run.stdout==expected,(case,phase,run.returncode,run.stdout,run.stderr)
   assert file.read_bytes()==after
   rss=re.search(rb'^\s*(\d+)\s+maximum resident set size\s*$',run.stderr,re.M);assert rss
   records.append({'case':case,'phase':phase,'warmup':repetition==0,'seconds':elapsed,'rss_bytes':int(rss[1])})
summary={case:{phase:{'median_seconds':statistics.median(r['seconds'] for r in records if r['case']==case and r['phase']==phase and not r['warmup']),'median_rss_bytes':statistics.median(r['rss_bytes'] for r in records if r['case']==case and r['phase']==phase and not r['warmup'])} for phase in binaries} for case in ('show-last','remove-last')}
report={'scope':'Small rotating paired native Release sample, not CP42 performance acceptance; d099 retained prior artifact, unhoisted/hoisted built with same D100 compiler','compiler_sha256':hashlib.sha256(COMPILER.read_bytes()).hexdigest(),'binary_sha256':{k:hashlib.sha256(v.read_bytes()).hexdigest() for k,v in binaries.items()},'dataset':{'notes':6098,'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest()},'records':records,'summary':summary,'driver':Path(__file__).read_text()}
